<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Services\SchoolFees;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Carbon\CarbonImmutable;
class FeeCollectionsController extends Controller
{
 private const METHODS=['cash','bank_transfer','jazzcash','easypaisa'];
 public function __construct(private SchoolFees $fees){}
 private function school(int $sid):object{$s=DB::table('schools')->where('id',$sid)->first(['name','code']);$s->contact=json_decode(DB::table('school_settings')->where('school_id',$sid)->where('key','contact')->value('value')??'{}',true);return $s;}
 private function payment(int $sid,array $campuses,int $id):object{$p=$this->fees->row('payments',$sid,$id);abort_unless(in_array((int)$p->campus_id,$campuses,true),404);foreach(DB::table('payment_allocations')->where('school_id',$sid)->where('payment_id',$id)->get() as $a)$this->fees->invoice($sid,$campuses,$a->invoice_id);return $p;}
 public function collect(Request $r,int $invoice){$d=$r->validate(['amount'=>['required','regex:/^\d{1,8}(\.\d{1,2})?$/D'],'method'=>['required',Rule::in(self::METHODS)],'paid_on'=>'required|date_format:Y-m-d|before_or_equal:'.now('Asia/Karachi')->toDateString(),'bank_account_id'=>'nullable|integer','reference'=>'nullable|string|max:160','idempotency_key'=>'required|uuid']);
  $id=$this->fees->lock($r,'fees.collect',function($sid,$campuses)use($r,$d,$invoice){$i=$this->fees->invoice($sid,$campuses,$invoice);$amount=SchoolFees::cents($d['amount']);if($amount<=0)$this->fees->fail('Payment must be greater than zero.');$existing=DB::table('payments')->where('school_id',$sid)->where('idempotency_key',$d['idempotency_key'])->first();if($existing){$this->payment($sid,$campuses,$existing->id);$a=DB::table('payment_allocations')->where('school_id',$sid)->where('payment_id',$existing->id)->get();$date=CarbonImmutable::parse($existing->paid_at,'UTC')->setTimezone('Asia/Karachi')->toDateString();if($a->count()!==1||$a->first()->invoice_id!=$invoice||SchoolFees::cents($existing->amount)!==$amount||$existing->method!==$d['method']||$date!==$d['paid_on']||($existing->bank_account_id??null)!=($d['bank_account_id']??null)||($existing->reference??'')!==($d['reference']??''))$this->fees->fail('This payment key was used for different details. Refresh before creating a different payment.');return $existing->id;}
   if($i->status==='void')$this->fees->fail('Cannot collect against a void invoice.');$balance=SchoolFees::cents($this->fees->totals($sid,$i)['balance']);if($amount>$balance)$this->fees->fail('Payment exceeds the outstanding balance.');if($d['paid_on']<$i->issued_on)$this->fees->fail('Payment date cannot be before invoice issue date.');
   if($d['method']!=='cash'&&(empty($d['bank_account_id'])||empty($d['reference'])))$this->fees->fail('Non-cash collections require a bank/wallet account and transaction reference.');if($d['method']==='cash'&&!empty($d['bank_account_id']))$this->fees->fail('Cash collections must not use a bank account.');$this->fees->bank($sid,$campuses,$d['bank_account_id']??null,(int)$i->enrollment->campus_id);
   if($d['method']!=='cash'&&DB::table('payments')->where('school_id',$sid)->where('bank_account_id',$d['bank_account_id'])->where('reference',$d['reference'])->whereNotExists(fn($q)=>$q->selectRaw('1')->from('payment_reversals as rev')->whereColumn('rev.payment_id','payments.id')->whereColumn('rev.school_id','payments.school_id')->where('rev.status','approved')->where('rev.kind','correction')->whereColumn('rev.amount','payments.amount'))->exists())$this->fees->fail('This account/transaction reference has already been recorded.');
   $id=DB::table('payments')->insertGetId(['school_id'=>$sid,'campus_id'=>$i->enrollment->campus_id,'student_id'=>$i->enrollment->student_id,'bank_account_id'=>$d['bank_account_id']??null,'received_by'=>$this->fees->access->membership($r)->id,'receipt_no'=>$this->fees->number('RCT',$sid,'payments'),'amount'=>SchoolFees::money($amount),'method'=>$d['method'],'reference'=>$d['reference']??null,'paid_at'=>CarbonImmutable::parse($d['paid_on'].' 12:00:00','Asia/Karachi')->utc()->format('Y-m-d H:i:s'),'idempotency_key'=>$d['idempotency_key'],'created_at'=>now(),'updated_at'=>now()]);DB::table('payment_allocations')->insert(['school_id'=>$sid,'payment_id'=>$id,'invoice_id'=>$invoice,'amount'=>SchoolFees::money($amount),'created_at'=>now(),'updated_at'=>now()]);$this->fees->refresh($sid,$invoice);$this->fees->access->audit($r,'fees.payment_collected','payments',$id,['invoice_id'=>$invoice,'amount'=>SchoolFees::money($amount),'method'=>$d['method']]);return $id;});return response()->json(['id'=>$id,'message'=>'Payment recorded.']);}
 public function requestReversal(Request $r,int $payment){$d=$r->validate(['kind'=>['required',Rule::in(['correction','refund'])],'amount'=>['required','regex:/^\d{1,8}(\.\d{1,2})?$/D'],'reason'=>'required|string|min:5|max:1000','refund_method'=>['nullable',Rule::in(self::METHODS)],'refund_bank_account_id'=>'nullable|integer','refund_reference'=>'nullable|string|max:160','idempotency_key'=>'required|uuid']);$id=$this->fees->lock($r,'fees.request_reversal',function($sid,$campuses)use($r,$d,$payment){$p=$this->payment($sid,$campuses,$payment);$amount=SchoolFees::cents($d['amount']);$existing=DB::table('payment_reversals')->where('school_id',$sid)->where('idempotency_key',$d['idempotency_key'])->first();if($existing){if($existing->payment_id!=$payment||SchoolFees::cents($existing->amount)!==$amount||$existing->kind!==$d['kind']||$existing->reason!==$d['reason']||($existing->refund_method??'')!==($d['refund_method']??'')||($existing->refund_reference??'')!==($d['refund_reference']??'')||($existing->refund_bank_account_id??null)!=($d['refund_bank_account_id']??null))$this->fees->fail('Reversal key already used for different details.');return $existing->id;}
   $pending=(int)DB::table('payment_reversals')->where('school_id',$sid)->where('payment_id',$payment)->where('status','pending')->selectRaw('COALESCE(SUM(amount)*100,0) as cents')->value('cents');$net=$this->fees->netPayment($sid,$p);if($amount<=0||$amount>$net-$pending)$this->fees->fail('Requested reversal exceeds the available payment amount.');if(DB::table('payment_allocations')->where('school_id',$sid)->where('payment_id',$payment)->count()!==1&&$amount!==$net)$this->fees->fail('Legacy multi-invoice payments support full reversal only.');
   if($d['kind']==='refund'){if(empty($d['refund_method']))$this->fees->fail('Select the actual refund method.');if($d['refund_method']!=='cash'&&(empty($d['refund_bank_account_id'])||empty($d['refund_reference'])))$this->fees->fail('Non-cash refunds need a bank/wallet account and reference.');if($d['refund_method']==='cash'&&!empty($d['refund_bank_account_id']))$this->fees->fail('Cash refund must not use a bank account.');$this->fees->bank($sid,$campuses,$d['refund_bank_account_id']??null,(int)$p->campus_id);}elseif(!empty($d['refund_method'])||!empty($d['refund_bank_account_id'])||!empty($d['refund_reference']))$this->fees->fail('A correction does not record money paid back. Clear refund details.');
   $id=DB::table('payment_reversals')->insertGetId($d+['school_id'=>$sid,'payment_id'=>$payment,'status'=>'pending','reversed_by'=>$this->fees->access->membership($r)->id,'created_at'=>now(),'updated_at'=>now()]);$this->fees->access->audit($r,'fees.reversal_requested','payment_reversals',$id,['payment_id'=>$payment,'kind'=>$d['kind'],'amount'=>$d['amount'],'reason'=>$d['reason']]);return $id;});return response()->json(['id'=>$id,'message'=>'Reversal request recorded; approval required.']);}
 public function reviewReversal(Request $r,int $reversal){$d=$r->validate(['decision'=>['required',Rule::in(['approve','reject'])]]);$this->fees->lock($r,'fees.approve_reversal',function($sid,$campuses)use($r,$d,$reversal){$rev=$this->fees->row('payment_reversals',$sid,$reversal);$p=$this->payment($sid,$campuses,$rev->payment_id);$target=$d['decision']==='approve'?'approved':'rejected';if($rev->status===$target)return;if($rev->status!=='pending')$this->fees->fail('This request has already been reviewed.');if($target==='approved'&&SchoolFees::cents($rev->amount)>$this->fees->netPayment($sid,$p))$this->fees->fail('Reversal exceeds remaining payment.');DB::table('payment_reversals')->where('school_id',$sid)->where('id',$reversal)->update(['status'=>$target,'approved_by'=>$this->fees->access->membership($r)->id,'reversed_at'=>$target==='approved'?now():null,'updated_at'=>now()]);foreach(DB::table('payment_allocations')->where('school_id',$sid)->where('payment_id',$p->id)->pluck('invoice_id') as $invoice)$this->fees->refresh($sid,$invoice);$this->fees->access->audit($r,'fees.reversal_'.$target,'payment_reversals',$reversal,['payment_id'=>$p->id,'kind'=>$rev->kind,'amount'=>$rev->amount]);});return response()->json(['message'=>'Reversal request reviewed.']);}
 public function invoice(Request $r,int $invoice){[$sid,$campuses]=$this->fees->context($r);$i=$this->fees->invoice($sid,$campuses,$invoice);$i=(object)(get_object_vars($i)+$this->fees->totals($sid,$i));$payments=DB::table('payments as p')->join('payment_allocations as a','a.payment_id','=','p.id')->where('a.school_id',$sid)->where('a.invoice_id',$invoice)->orderByDesc('p.id')->get(['p.*']);foreach($payments as $p){$p->net=SchoolFees::money($this->fees->netPayment($sid,$p));unset($p->idempotency_key);}
  return response()->json(['school'=>$this->school($sid),'invoice'=>$i,'items'=>DB::table('invoice_items')->where('school_id',$sid)->where('invoice_id',$invoice)->get(),'payments'=>$payments,'reversals'=>DB::table('payment_reversals')->where('school_id',$sid)->whereIn('payment_id',$payments->pluck('id'))->get(['id','payment_id','amount','kind','reason','status','refund_method','refund_reference','reversed_at'])]);}
 public function receipt(Request $r,int $payment){[$sid,$campuses]=$this->fees->context($r);$p=$this->payment($sid,$campuses,$payment);$p->net=SchoolFees::money($this->fees->netPayment($sid,$p));$p->paid_on=CarbonImmutable::parse($p->paid_at,'UTC')->setTimezone('Asia/Karachi')->toDateString();$p->collector=DB::table('school_memberships as m')->join('users as u','u.id','=','m.user_id')->where('m.school_id',$sid)->where('m.id',$p->received_by)->value('u.name');$p->campus_name=DB::table('campuses')->where('school_id',$sid)->where('id',$p->campus_id)->value('name');unset($p->idempotency_key);return response()->json(['school'=>$this->school($sid),'payment'=>$p,'student'=>DB::table('students')->where('school_id',$sid)->where('id',$p->student_id)->first(['first_name','last_name','admission_no']),'allocations'=>DB::table('payment_allocations as a')->join('invoices as i','i.id','=','a.invoice_id')->where('a.school_id',$sid)->where('a.payment_id',$payment)->get(['i.number','a.amount']),'reversals'=>DB::table('payment_reversals')->where('school_id',$sid)->where('payment_id',$payment)->get(['id','amount','kind','reason','status','refund_method','refund_reference','reversed_at'])]);}
 public function invoices(Request $r){[$sid,$campuses]=$this->fees->context($r);$d=$r->validate(['search'=>'nullable|string|max:100','campus_id'=>'nullable|integer','student_id'=>'nullable|integer','status'=>['nullable',Rule::in(['unpaid','partial','paid','void','overdue'])],'page'=>'nullable|integer|min:1']);$q=$this->invoiceQuery($sid,$campuses);if(!empty($d['search']))$q->where(fn($q)=>$q->where('i.number','like','%'.$d['search'].'%')->orWhere('st.admission_no','like','%'.$d['search'].'%')->orWhereRaw("CONCAT_WS(' ',st.first_name,st.last_name) LIKE ?",['%'.$d['search'].'%']));if(!empty($d['campus_id']))$q->where('s.campus_id',$d['campus_id']);if(!empty($d['student_id']))$q->where('st.id',$d['student_id']);if(($d['status']??'')==='overdue')$q->whereIn('i.status',['unpaid','partial'])->where('i.due_on','<',now('Asia/Karachi')->toDateString());elseif(!empty($d['status']))$q->where('i.status',$d['status']);$rows=$q->orderByDesc('i.id')->paginate(25,['i.*','st.first_name','st.last_name','st.admission_no','st.id as student_id','s.campus_id']);$this->fees->primePaid($sid,$rows->pluck('id')->all());foreach($rows as $i)foreach($this->fees->totals($sid,$i) as $key=>$value)$i->$key=$value;return response()->json($rows);}
 private function invoiceQuery(int $sid,array $campuses){return DB::table('invoices as i')->join('enrollments as e','e.id','=','i.enrollment_id')->join('sections as s','s.id','=','e.section_id')->join('students as st','st.id','=','e.student_id')->where('i.school_id',$sid)->whereIn('s.campus_id',$campuses);}
 public function reports(Request $r){return DB::transaction(fn()=>$this->reportData($r));}
 private function reportData(Request $r){[$sid,$campuses]=$this->fees->context($r);$d=$r->validate(['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d|after_or_equal:from','campus_id'=>'nullable|integer','student_id'=>'nullable|integer']);$scope=$campuses;if(!empty($d['campus_id']))$scope=array_values(array_intersect($scope,[(int)$d['campus_id']]));$from=CarbonImmutable::parse($d['from'],'Asia/Karachi')->startOfDay()->utc();$to=CarbonImmutable::parse($d['to'],'Asia/Karachi')->endOfDay()->utc();$q=$this->invoiceQuery($sid,$scope)->where('i.issued_on','<=',$d['to']);if(!empty($d['student_id']))$q->where('st.id',$d['student_id']);$ledger=[];$outstanding=0;$overdue=0;
  $invoices=$q->orderBy('i.issued_on')->orderBy('i.id')->get(['i.*','st.admission_no','st.first_name','st.last_name','st.id as student_id']);$this->fees->primePaid($sid,$invoices->pluck('id')->all());foreach($invoices as $i){$t=$this->fees->totals($sid,$i);$balance=SchoolFees::cents($t['balance']);$outstanding+=$balance;if($i->due_on<now('Asia/Karachi')->toDateString())$overdue+=$balance;if($balance>0||!empty($d['student_id']))$ledger[]=get_object_vars($i)+$t;}
  $p=DB::table('payments')->where('school_id',$sid)->whereIn('campus_id',$scope)->whereBetween('paid_at',[$from,$to]);if(!empty($d['student_id']))$p->where('student_id',$d['student_id']);$payments=$p->orderByDesc('paid_at')->get(['id','receipt_no','student_id','amount','method','reference','paid_at']);$gross=0;$methods=[];foreach($payments as $pay){$v=SchoolFees::cents($pay->amount);$gross+=$v;$methods[$pay->method]=($methods[$pay->method]??0)+$v;$pay->paid_on=CarbonImmutable::parse($pay->paid_at,'UTC')->setTimezone('Asia/Karachi')->toDateString();}
  $rev=DB::table('payment_reversals as r')->join('payments as p','p.id','=','r.payment_id')->where('r.school_id',$sid)->whereIn('p.campus_id',$scope)->where('r.status','approved')->whereBetween('r.reversed_at',[$from,$to]);if(!empty($d['student_id']))$rev->where('p.student_id',$d['student_id']);$reversals=$rev->get(['r.id','r.payment_id','r.amount','r.kind','r.refund_method','r.reason','r.reversed_at','p.receipt_no']);$refunds=0;$corrections=0;foreach($reversals as $row){if($row->kind==='refund')$refunds+=SchoolFees::cents($row->amount);else $corrections+=SchoolFees::cents($row->amount);}
  return response()->json(['from'=>$d['from'],'to'=>$d['to'],'gross'=>SchoolFees::money($gross),'refunds'=>SchoolFees::money($refunds),'corrections'=>SchoolFees::money($corrections),'net'=>SchoolFees::money($gross-$refunds-$corrections),'outstanding'=>SchoolFees::money($outstanding),'overdue'=>SchoolFees::money($overdue),'methods'=>array_map(fn($v)=>SchoolFees::money($v),$methods),'payments'=>$payments,'reversals'=>$reversals,'ledger'=>$ledger,'balance_note'=>'Outstanding and ledger reflect current approved payments, for invoices issued through the selected end date; they are not a historical closing balance. Collections/reversals use Pakistan dates.']);}
}
